  if(((Number)operation.get("reconcile_epoch")).longValue()>=Long.MAX_VALUE-1)throw new ama.contract.TranscriptContracts.Failure(409,"PUBLICATION_RETRY_EXHAUSTED");
  require("FAILED".equals(operation.get("state")),CAPABILITY_UNAVAILABLE);
  var executions=graph.rows().get("external_execution").stream().filter(e->operation.get("id").equals(e.get("operation_id"))&&((Number)e.get("execution_no")).longValue()==expected).toList();require(executions.size()==1,PROVENANCE_UNAVAILABLE);var execution=executions.getFirst();
