  var submissions=graph.rows().get("publication_submission").stream().filter(x->publication.equals(x.get("publication_id"))).sorted(Comparator.comparingLong(x->((Number)x.get("submission_no")).longValue())).toList();require(!submissions.isEmpty(),PROVENANCE_UNAVAILABLE);var submission=submissions.getLast();
