 private static boolean fixedValue(Object original,Object replacement){if(original instanceof Number a&&replacement instanceof Number b)return new java.math.BigDecimal(a.toString()).compareTo(new java.math.BigDecimal(b.toString()))==0;return Objects.equals(original,replacement);}
